package com.crms.entity;import jakarta.validation.constraints.*;import org.springframework.data.annotation.Id;import org.springframework.data.mongodb.core.mapping.Document;@Document("students") public class Student{@Id private Long id;private User user;private String phone,department,branch,skills,resumePath;@DecimalMin("0")@DecimalMax("10") private Double cgpa;private Integer graduationYear,backlogs;public Long getId(){return id;}public void setId(Long v){id=v;}public User getUser(){return user;}public void setUser(User v){user=v;}public String getPhone(){return phone;}public void setPhone(String v){phone=v;}public String getDepartment(){return department;}public void setDepartment(String v){department=v;}public String getBranch(){return branch;}public void setBranch(String v){branch=v;}public String getSkills(){return skills;}public void setSkills(String v){skills=v;}public Double getCgpa(){return cgpa;}public void setCgpa(Double v){cgpa=v;}public Integer getGraduationYear(){return graduationYear;}public void setGraduationYear(Integer v){graduationYear=v;}public Integer getBacklogs(){return backlogs;}public void setBacklogs(Integer v){backlogs=v;}public String getResumePath(){return resumePath;}public void setResumePath(String v){resumePath=v;}}
